//! Request-loss, exact receipt and actual compact-owner controls.
use super::*;
use crate::config::RELIABLE_RETRANSMIT_MS;
use std::sync::{Mutex,atomic::{AtomicU64,Ordering}};
type Wire=Arc<Mutex<Vec<Vec<u8>>>>;
fn side(node:&Router,name:&str)->(usize,Wire) {let wire=Arc::new(Mutex::new(Vec::new()));let out=wire.clone();let id=node.add_side_packed_with_options(name,move|b|{out.lock().unwrap().push(b.to_vec());Ok(())},RouterSideOptions{reliable_enabled:true,link_local_enabled:false,..Default::default()});(id,wire)}
fn node(name:&str,clock:&Arc<AtomicU64>)->Router {let now=clock.clone();Router::new_with_clock(RouterConfig::new([]).with_sender(name),Box::new(move||now.load(Ordering::SeqCst)))}
fn target(name:&str)->(DataType,DataEndpoint) {let ep=crate::config::register_endpoint_with_description(&format!("{name}_ENDPOINT"),"caller-owned",false).unwrap();let ty=crate::config::register_data_type_with_description(name,"caller-owned managed sample",crate::MessageElement::Static(1,crate::MessageDataType::UInt32,crate::MessageClass::Data),&[ep],crate::ReliableMode::Ordered,80).unwrap();(ty,ep)}
fn peers(node:&Router,side:usize) {for name in ["GET_A","GET_B"] {node.rx_from_side(&discovery::build_discovery_announce(name,1000,&[DataEndpoint::Discovery]).unwrap(),side).unwrap();}node.clear_queues();}
fn writer(name:&str)->(Router,usize,Wire,Arc<AtomicU64>,DataType,u64) {crate::tests::ensure_common_test_schema();let clock=Arc::new(AtomicU64::new(1000));let writer=node(name,&clock);let(ws,out)=side(&writer,"requesters");let(ty,ep)=target(&format!("{name}_VALUE"));writer.enable_network_variable(ty,NetworkVariablePermissions::READ_WRITE).unwrap();let value=Packet::new(ty,&[ep],name,42,Arc::<[u8]>::from(91u32.to_le_bytes())).unwrap();let id=value.packet_id();writer.set_network_variable(value).unwrap();peers(&writer,ws);out.lock().unwrap().clear();(writer,ws,out,clock,ty,id)}
fn request(node:&Router,side:usize,out:&Wire,ty:DataType,stamp:u64)->(u64,Vec<u8>,u32) {let packet=discovery::build_managed_variable_request(node.sender_arc().as_ref(),stamp,ty).unwrap();let id=packet.packet_id();node.send_reliable_to_side(side,RouterItem::Packet(packet),false).unwrap();let wire=out.lock().unwrap().iter().find(|wire|wire_format::packet_id_from_wire(wire).ok()==Some(id)).unwrap().clone();let seq=wire_format::peek_frame_info(&wire).unwrap().reliable.unwrap().seq;(id,wire,seq)}
fn ack(out:&Wire,id:u64)->Vec<u8> {out.lock().unwrap().iter().rev().find(|wire|wire_format::unpack_packet(wire).is_ok_and(|p|p.data_type()==DataType::ReliableAck&&p.payload()==id.to_le_bytes()&&p.wire_target_senders().len()==2)).expect("real bound GET receipt").clone()}
fn pending(node:&Router,side:usize,ty:DataType)->Vec<u32> {node.state.lock().reliable_tx.get(&Router::reliable_key(side,ty)).map(|row|row.sent.keys().copied().collect()).unwrap_or_default()}
#[test]
fn request_policy_is_exact_and_keeps_get_schema_values_and_application_ordering() {let clock=Arc::new(AtomicU64::new(1000));let source=node("REQUEST_POLICY",&clock);let(s,out)=side(&source,"peer");source.clear_queues();for packet in [discovery::build_discovery_topology_request("REQUEST_POLICY",1001).unwrap(),discovery::build_discovery_schema_request("REQUEST_POLICY",1002).unwrap()] {let ty=packet.data_type();let id=packet.packet_id();source.send_reliable_to_side(s,RouterItem::Packet(packet),false).unwrap();let w=out.lock().unwrap().iter().find(|wire|wire_format::packet_id_from_wire(wire).ok()==Some(id)).unwrap().clone();let header=wire_format::peek_frame_info(&w).unwrap().reliable.unwrap();assert_eq!((header.seq,header.flags),(0,wire_format::RELIABLE_FLAG_UNSEQUENCED));assert!(pending(&source,s,ty).is_empty());}
    for ty in [DataType::DiscoverySchema,DataType::ManagedVariableRequest,DataType::ManagedVariableValue,DataType::P2pMessage] {assert!(!discovery::is_periodic_discovery_request_type(ty));}
    assert!(!is_bound_network_control(DataType::ManagedVariableValue));assert!(!is_bound_network_control(DataType::P2pMessage));
    let(ty,ep)=target("APP_ORDERED_POLICY");let packet=Packet::new(ty,&[ep],"REQUEST_POLICY",1003,Arc::<[u8]>::from(4u32.to_le_bytes())).unwrap();source.send_reliable_to_side(s,RouterItem::Packet(packet),false).unwrap();assert_eq!(pending(&source,s,ty),vec![1]);
}
#[test]
fn lost_get_and_lost_receipt_retry_same_original_without_restamping_cached_value() {let(writer,ws,out,clock,ty,value_id)=writer("LOSS_WRITER");let sender=node("GET_A",&clock);let(ss,sent)=side(&sender,"writer");sender.clear_queues();let(id,first,seq)=request(&sender,ss,&sent,ty,1001);assert_eq!(seq,1); // first request is deliberately not delivered
    clock.fetch_add(RELIABLE_RETRANSMIT_MS+1,Ordering::SeqCst);sender.process_all_queues().unwrap();let attempts=sent.lock().unwrap().iter().filter(|wire|wire_format::packet_id_from_wire(wire).ok()==Some(id)).cloned().collect::<Vec<_>>();assert!(attempts.len()>=2);writer.rx_packed_from_side(attempts.last().unwrap(),ws).unwrap();writer.process_all_queues().unwrap();let _first_receipt=ack(&out,id); // deliberately lost
    assert_eq!(pending(&sender,ss,DataType::ManagedVariableRequest),vec![1]);clock.fetch_add(RELIABLE_RETRANSMIT_MS+1,Ordering::SeqCst);sender.process_all_queues().unwrap();writer.rx_packed_from_side(&first,ws).unwrap();writer.process_all_queues().unwrap();sender.rx_packed_from_side(&ack(&out,id),ss).unwrap();assert!(pending(&sender,ss,DataType::ManagedVariableRequest).is_empty());
    let values=out.lock().unwrap().iter().filter_map(|wire|wire_format::unpack_packet(wire).ok()).filter(|p|p.data_type()==ty).collect::<Vec<_>>();assert!(!values.is_empty());assert!(values.iter().all(|p|p.timestamp()==42&&p.packet_id()==value_id));
}
#[test]
fn two_get_publishers_same_seq_retire_only_their_own_original() {let(writer,ws,out,clock,ty,_)=writer("TWO_GET_WRITER");let a=node("GET_A",&clock);let b=node("GET_B",&clock);let(as_,ao)=side(&a,"writer");let(bs,bo)=side(&b,"writer");a.clear_queues();b.clear_queues();let(aid,aw,aseq)=request(&a,as_,&ao,ty,1001);let(bid,bw,bseq)=request(&b,bs,&bo,ty,1001);assert_eq!((aseq,bseq),(1,1));assert_ne!(aid,bid);writer.rx_packed_from_side(&aw,ws).unwrap();writer.process_all_queues().unwrap();let first=ack(&out,aid);a.rx_packed_from_side(&first,as_).unwrap();b.rx_packed_from_side(&first,bs).unwrap();assert!(pending(&a,as_,DataType::ManagedVariableRequest).is_empty());assert_eq!(pending(&b,bs,DataType::ManagedVariableRequest),vec![1]);writer.rx_packed_from_side(&bw,ws).unwrap();writer.process_all_queues().unwrap();b.rx_packed_from_side(&ack(&out,bid),bs).unwrap();assert!(pending(&b,bs,DataType::ManagedVariableRequest).is_empty());}
#[test]
fn malformed_self_get_and_schema_never_receive_bound_receipts() {let(writer,ws,out,_,_,_)=writer("SELF_INVALID_WRITER");for ty in [DataType::ManagedVariableRequest,DataType::DiscoverySchema] {let packet=Packet::new(ty,&[DataEndpoint::Discovery],"SELF_INVALID_WRITER",1002,Arc::<[u8]>::from([255,7,0])).unwrap();let id=packet.packet_id();let bytes=wire_format::pack_packet_with_reliable(&packet,wire_format::ReliableHeader{flags:0,seq:1,ack:0});assert!(writer.rx_packed_from_side(&bytes,ws).is_err());assert!(out.lock().unwrap().iter().all(|wire|wire_format::unpack_packet(wire).map_or(true,|p|!(p.data_type()==DataType::ReliableAck&&p.payload()==id.to_le_bytes()&&p.wire_target_senders().len()==2))));}}
#[test]
fn read_only_get_requires_forward_admission_and_does_not_invent_a_value() {let clock=Arc::new(AtomicU64::new(1000));let replica=node("READ_ONLY_REPLICA",&clock);let(rs,out)=side(&replica,"readers");let(ty,_)=target("READ_ONLY_GET_TARGET");replica.enable_network_variable(ty,NetworkVariablePermissions::READ_ONLY).unwrap();peers(&replica,rs);out.lock().unwrap().clear();let sender=node("GET_A",&clock);let(ss,sent)=side(&sender,"replica");let(id,wire,_)=request(&sender,ss,&sent,ty,1001);replica.rx_packed_from_side(&wire,rs).unwrap();assert!(!replica.state.lock().recent_rx.contains(&id));{let state=replica.state.lock();let request=state.discovery_routes[&rs].requested_network_variables.iter().find(|request|request.ty==ty).expect("actual bounded subscription admitted before processing receipt");assert_eq!(request.request_id,id);assert_eq!(request.requester,sender_address_u32("GET_A"));}replica.process_all_queues().unwrap();let _lost_leaf_processing_receipt=ack(&out,id);assert!(replica.get_cached_network_variable(ty).unwrap().is_none());let(_,forwarded)=side(&replica,"writer link");replica.rx_packed_from_side(&wire,rs).unwrap();replica.process_all_queues().unwrap();assert!(forwarded.lock().unwrap().iter().any(|wire|wire_format::packet_id_from_wire(wire).ok()==Some(id)));sender.rx_packed_from_side(&ack(&out,id),ss).unwrap();assert!(pending(&sender,ss,DataType::ManagedVariableRequest).is_empty());assert!(replica.get_cached_network_variable(ty).unwrap().is_none());}
#[test]
fn both_control_classes_are_charged_and_existing_configured_limit_refuses_the_second() {
    const CHILD:&str="SEDS_BOUND_TWO_CLASS_LIMIT_CHILD";
    if std::env::var_os(CHILD).is_none() {let output=std::process::Command::new(std::env::current_exe().unwrap()).args(["--exact","router::network_control_receipt_tests::both_control_classes_are_charged_and_existing_configured_limit_refuses_the_second","--nocapture"]).env(CHILD,"1").output().unwrap();assert!(output.status.success(),"{}{}",String::from_utf8_lossy(&output.stdout),String::from_utf8_lossy(&output.stderr));return}
    let clock=Arc::new(AtomicU64::new(1000));let node=node("COLD_CONTROL_LIMIT",&clock);let(s,out)=side(&node,"peer");node.clear_queues();out.lock().unwrap().clear();let binding=Router::side_ref(&node.state.lock(),s).unwrap().tx_handler.clone();let original=crate::config::runtime_tuning_config();let mut limited=original;limited.reliable_max_pending=1;crate::config::set_runtime_tuning_config(limited).unwrap();node.reserve_bound_control_mode(s,DataType::DiscoverySchema,&binding).unwrap();assert!(node.reserve_bound_control_mode(s,DataType::ManagedVariableRequest,&binding).is_err());assert!(out.lock().unwrap().is_empty());crate::config::set_runtime_tuning_config(original).unwrap();let before=node.state.lock().reliable_rx_buffered_bytes();node.reserve_bound_control_mode(s,DataType::ManagedVariableRequest,&binding).unwrap();let after=node.state.lock().reliable_rx_buffered_bytes();assert!(after>=before+CONTROL_RX_ROW_LOGICAL_BYTES+CONTROL_RX_TAG_LOGICAL_BYTES);assert_eq!(node.state.lock().reliable_rx.len(),2);assert!(node.reserve_bound_control_mode(s,DataType::ManagedVariableValue,&binding).is_err());
}
#[cfg(feature="compact-packet-store")]
struct ArenaReset;
#[cfg(feature="compact-packet-store")]
impl Drop for ArenaReset {fn drop(&mut self){crate::packet_store::set_default_store(None);}}
#[test]
#[cfg(feature="compact-packet-store")]
fn actual_global_managed_schema_owner_survives_compaction_without_pins() {let _reset=ArenaReset;let store=crate::packet_store::PacketStore::new(256*1024,1024,usize::MAX).unwrap();crate::packet_store::set_default_store(Some(store.clone()));let hole=store.store(&[0;128]).unwrap();let clock=Arc::new(AtomicU64::new(1000));let sender=node("MANAGED_SCHEMA_A",&clock);let(ss,sent)=side(&sender,"receiver");let receiver=node("MANAGED_RECEIVER",&clock);let(rs,out)=side(&receiver,"shared");for name in ["MANAGED_SCHEMA_A","MANAGED_SCHEMA_B"] {receiver.rx_from_side(&discovery::build_discovery_announce(name,1000,&[DataEndpoint::Discovery]).unwrap(),rs).unwrap();}sender.clear_queues();receiver.clear_queues();sent.lock().unwrap().clear();out.lock().unwrap().clear();let packet=discovery::build_discovery_schema("MANAGED_SCHEMA_A",1001).unwrap();let id=packet.packet_id();sender.send_reliable_to_side(ss,RouterItem::Packet(packet),false).unwrap();{let state=sender.state.lock();assert!(matches!(state.reliable_tx[&Router::reliable_key(ss,DataType::DiscoverySchema)].sent[&1].bytes,crate::small_payload::SmallPayload::Managed(_)));}assert_eq!(store.stats().pinned_bytes,0);let before=store.stats().moves;drop(hole);store.compact();assert!(store.stats().moves>before);let wire=sent.lock().unwrap().iter().find(|wire|wire_format::packet_id_from_wire(wire).ok()==Some(id)).unwrap().clone();receiver.rx_packed_from_side(&wire,rs).unwrap();receiver.process_all_queues().unwrap();sender.rx_packed_from_side(&ack(&out,id),ss).unwrap();assert!(pending(&sender,ss,DataType::DiscoverySchema).is_empty());assert_eq!(store.stats().pinned_bytes,0);}
#[test]
#[cfg(feature="compact-packet-store")]
fn managed_owner_comparison_is_identity_not_equal_bytes_or_slot_number() {let store=crate::packet_store::PacketStore::new(4096,16,usize::MAX).unwrap();let other=crate::packet_store::PacketStore::new(4096,16,usize::MAX).unwrap();let left=crate::small_payload::SmallPayload::<0>::Managed(crate::packet_store::ParkedPayload::new(store.store(&[1,2,3]).unwrap()));let alias=left.clone();let same_bytes=crate::small_payload::SmallPayload::<0>::Managed(crate::packet_store::ParkedPayload::new(store.store(&[1,2,3]).unwrap()));let other_store=crate::small_payload::SmallPayload::<0>::Managed(crate::packet_store::ParkedPayload::new(other.store(&[1,2,3]).unwrap()));assert!(crate::shared_bytes::same_owner(&left,&alias));assert!(!crate::shared_bytes::same_owner(&left,&same_bytes));assert!(!crate::shared_bytes::same_owner(&left,&other_store));assert_eq!(store.stats().pinned_bytes,0);assert_eq!(other.stats().pinned_bytes,0);}
#[test]
fn get_reserved_token_cannot_publish_after_real_side_remove_readd() {let(writer,ws,out,clock,ty,_)=writer("GET_ABA_WRITER");let old_binding=Router::side_ref(&writer.state.lock(),ws).unwrap().tx_handler.clone();let old_token=writer.reserve_bound_control_mode(ws,DataType::ManagedVariableRequest,&old_binding).unwrap();let packet=discovery::build_managed_variable_request("GET_A",1001,ty).unwrap();discovery::decode_managed_variable_request(&packet).unwrap();let id=packet.packet_id();let receipt=writer.build_end_to_end_ack_data(id,Router::sender_hash("GET_A")).unwrap();let priority=Router::router_item_priority(&receipt).unwrap();writer.remove_side(ws).unwrap();let(new_side,new_out)=side(&writer,"replacement query side");assert_eq!(new_side,ws);let new_binding=Router::side_ref(&writer.state.lock(),new_side).unwrap().tx_handler.clone();let new_token=writer.reserve_bound_control_mode(new_side,DataType::ManagedVariableRequest,&new_binding).unwrap();assert!(new_token>old_token);assert!(writer.commit_bound_control_receipt(ws,DataType::ManagedVariableRequest,old_token,&old_binding,receipt,priority).is_err());assert!(out.lock().unwrap().iter().all(|wire|wire_format::unpack_packet(wire).map_or(true,|p|p.data_type()!=DataType::ReliableAck||p.payload()!=id.to_le_bytes())));assert!(new_out.lock().unwrap().is_empty());assert_eq!(clock.load(Ordering::SeqCst),1000);}
